export function isPermissionKey(value: string): value is PermissionKey { return PERMISSION_KEYS.has(value); }
export function validatePermissionKeys(values: unknown): string[] {
  if (!Array.isArray(values)) return [];
  return values.filter((value): value is string => typeof value === 'string' && PERMISSION_KEYS.has(value));
}
